mapper.select:
SELECT f.fund_code AS fundCode, f.fund_name AS fundName, f.fund_type AS fundType, f.company, f.manager, f.establish_date AS establishDate, f.nav, f.accumulated_nav AS accumulatedNav, f.scale, ROUND((f.accumulated_nav - f.nav), 4) AS navGap FROM fund f
AND f.fund_type = #{fundType}
AND (f.fund_name LIKE CONCAT('%', #{keyword}, '%') OR f.fund_code LIKE CONCAT('%', #{keyword}, '%'))
AND f.company = #{company}
AND f.scale >= #{minScale}
AND f.scale <= #{maxScale}
ORDER BY f.nav ASC
ORDER BY f.nav DESC
ORDER BY f.scale ASC
ORDER BY f.scale DESC
ORDER BY f.scale DESC
LIMIT #{limit} OFFSET #{offset}
